-- P2 V-SEED-P2 cleanup. Run only with scripts/demo/clean-p2.ps1 (demo gate + loopback guard).
-- Includes TENANT_ADMIN secondary employment and the platform-admin demo account.
BEGIN;
DELETE FROM iam.iam_issued_context
 WHERE account_id IN (
     '01900000-0000-7000-8000-000000000201',
     '01900000-0000-7000-8000-000000000202',
     '01900000-0000-7000-8000-000000000221'
   )
    OR person_id IN (
     '01900000-0000-7000-8000-000000000203',
     '01900000-0000-7000-8000-000000000204',
     '01900000-0000-7000-8000-000000000222'
   );
DELETE FROM iam.perm_assignment WHERE id = '01900000-0000-7000-8000-000000000212';
DELETE FROM iam.perm_role WHERE id = '01900000-0000-7000-8000-000000000211';
DELETE FROM iam.iam_employment
 WHERE id IN (
   '01900000-0000-7000-8000-000000000209',
   '01900000-0000-7000-8000-000000000210',
   '01900000-0000-7000-8000-000000000216',
   '01900000-0000-7000-8000-000000000225'
 );
DELETE FROM iam.iam_department WHERE id IN (
  '01900000-0000-7000-8000-000000000206',
  '01900000-0000-7000-8000-000000000205',
  '01900000-0000-7000-8000-000000000226'
);
DELETE FROM iam.iam_position
 WHERE id IN (
   '01900000-0000-7000-8000-000000000207',
   '01900000-0000-7000-8000-000000000208',
   '01900000-0000-7000-8000-000000000215',
   '01900000-0000-7000-8000-000000000224'
 );
DELETE FROM iam.iam_person
 WHERE id IN (
   '01900000-0000-7000-8000-000000000203',
   '01900000-0000-7000-8000-000000000204',
   '01900000-0000-7000-8000-000000000222'
 );
DELETE FROM iam.iam_tenant_membership
 WHERE account_id IN (
   '01900000-0000-7000-8000-000000000201',
   '01900000-0000-7000-8000-000000000202',
   '01900000-0000-7000-8000-000000000221'
 );
DELETE FROM iam.iam_global_account
 WHERE id IN (
   '01900000-0000-7000-8000-000000000201',
   '01900000-0000-7000-8000-000000000202',
   '01900000-0000-7000-8000-000000000221'
 );
COMMIT;
